editorialMd:
Build visitOrder

A binary tree is a set of nodes, each with a value and up to two children: left and right. `root` is the top node. Visit a node by recording its value, then visit its whole left branch, then its whole right branch. Use this same rule at every node. Skip missing children. `visitOrder` is the recorded values. An empty tree gives an empty `visitOrder`.

Return the answer

Add up every number in `visitOrder`. Store the sum in `total`. Complete `branchNotebookTotalReceipt` so it returns `total`. Return it, do not print it.

Why this works

Each value in `visitOrder` follows task 1. The later tasks use only those values. Keeping these steps separate helps avoid returning the list when the question asks for one number. Check empty input, one item, repeated values, and the largest allowed input.

Efficiency goal: time O(n); extra memory, including the helper list, O(n). n is the number of nodes. These labels describe how work and memory grow with the input.

javascript
function branchNotebookTotalReceipt(root) {
  const a=root; let out=[];
  function visit(node){if(!node)return;out.push(node.val);visit(node.left);visit(node.right);}visit(a);
  return out.reduce((s,x)=>s+x,0);
}


typescript
type TreeNode = { val: number; left: TreeNode | null; right: TreeNode | null };
function branchNotebookTotalReceipt(root: TreeNode | null): number {
  const a=root; let out:number[]=[];
  function visit(node:TreeNode|null):void{if(!node)return;out.push(node.val);visit(node.left);visit(node.right);}visit(a);
  return out.reduce((s,x)=>s+x,0);
}


python
def branchNotebookTotalReceipt(root):
    a=root
    out=[]
    def visit(node):
        if not node: return
        out.append(node.val)
        visit(node.left)
        visit(node.right)
    visit(a)
    return sum(out)


java
class Solution {
  public int branchNotebookTotalReceipt(TreeNode root) {
    TreeNode a=root; List<Integer> out=new ArrayList<>();
    {class Walk {void visit(TreeNode node){if(node==null)return;out.add(node.val);visit(node.left);visit(node.right);}}new Walk().visit(a);}
    int answer=0;for(int x:out)answer+=x;return answer;
  }
}
